  // so the gate degrades to an optional lookup (the queue's own entries'
  // gates already ran in ProviderQueueRuntime.build).
  final key =
      defaultRoleResolved || customEndpoint || interactive || queueResolved
      ? (optionalProviderApiKey(
              provider,
